import { nativeRequest, parseIntent, decimalString, trustedConsoleConfig } from './native-console.js';
import { handoffGuidedIntent } from './guided-operations.js';
import { handoffKnownAsset } from './asset-handoff.js';

const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),check=(v,m)=>{if(!v)throw new Error(m);};
const json=v=>JSON.stringify(v,null,2),copy=v=>JSON.parse(JSON.stringify(v));
const freeze=v=>{if(object(v)||Array.isArray(v)){Object.values(v).forEach(freeze);Object.freeze(v);}return v;};
const U64=18446744073709551615n,U128=(1n<<128n)-1n,H_END=1611840n,FLOOR=288000000000000000n,K_WEIGHT=77760000000000n;
const RESOURCES={computeUnitLimit:1400000,loadedAccountsDataSizeLimit:67108864,heapSize:262144,priorityFeeLamports:'0'};
const B58='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function addressBytes(value){check(typeof value==='string'&&value.length>=32&&value.length<=44,'请输入完整公钥地址。');let n=0n;for(const c of value){const d=B58.indexOf(c);check(d>=0,'公钥包含无效字符。');n=n*58n+BigInt(d);}let h=n===0n?'':n.toString(16);if(h.length%2)h='0'+h;h='00'.repeat(value.match(/^1*/)[0].length)+h;check(h.length===64,'公钥必须编码32字节。');return h;}
const actor=v=>{const a=typeof v==='string'?v.trim():'';addressBytes(a);return a;};
const id=v=>{check(typeof v==='string'&&/^[0-9a-f]{64}$/.test(v),'实例ID必须是32字节小写hex。');return v;};
const uint=(v,max=U64)=>{check(typeof v==='string'&&v.length<=39&&/^(0|[1-9][0-9]*)$/.test(v)&&BigInt(v)<=max,'数值必须是规范的无符号十进制字符串。');return v;};
const cap=v=>decimalString(v),nullable=v=>v===null?null:uint(v);
const readonly=r=>check(object(r)&&r.clientPlanOnly===true&&r.transactionExecuted===false&&r.networkSubmitted===false,'返回结果缺少只读规划、未执行和未发送标记。');
const le=(h,at,n)=>{check(h.length/2>=at+n,'intent载荷被截断。');let v=0n;for(let i=n-1;i>=0;i--)v=v*256n+BigInt('0x'+h.slice((at+i)*2,(at+i+1)*2));return v;};
function ids(value){const list=Array.isArray(value)?value:typeof value==='string'?value.trim()?value.trim().split(/[\s,]+/):[]:null;check(list&&list.length<=4,'每次最多读取4个已知实例ID；留空可只读全网进度。');const out=list.map(id);check(new Set(out).size===out.length,'已知实例ID不能重复。');return out;}
export function miningReadRequest(v){const limit=Number(v.positionPageLimit);check(Number.isInteger(limit)&&limit>=1&&limit<=5,'每件作品每页只能读取1–5条Position。');return {actor:actor(v.actor),instancesHex:ids(v.instancesHex),positionPageStart:cap(v.positionPageStart),positionPageLimit:limit};}
export function miningGlobalRequest(v){return {actor:actor(v.actor),maxRent:cap(v.maxRent),resources:{...RESOURCES}};}
export function miningHourCloseRequest(v){const hour=cap(v.hour);check(BigInt(hour)<H_END,'小时必须处于实际排放区间内。');return {...miningGlobalRequest(v),hour};}
export function miningLifecycleRequest(v,kind){check(kind==='exit'||kind==='transfer','未知生命周期操作。');const q={...miningGlobalRequest(v),instanceHex:id(v.instanceHex),kind};if(kind==='transfer'){q.newOwner=actor(v.newOwner);check(q.newOwner!==q.actor,'新所有人必须与当前Actor不同。');}return q;}
function position(p,start,end,seen){check(object(p),'缺少实际Position。');const n=BigInt(uint(p.sequence));check(n>=start&&n<end&&!seen.has(p.positionIdHex),'Position重复或不属于本次请求页。');seen.add(id(p.positionIdHex));actor(p.beneficiary);for(const k of ['rootRevision','start','accruedAtoms','paidAtoms','claimableAtoms','nextUnsettledHour'])uint(p[k]);nullable(p.end);uint(p.weight,U128);check(BigInt(p.paidAtoms)<=BigInt(p.accruedAtoms)&&BigInt(p.claimableAtoms)===BigInt(p.accruedAtoms)-BigInt(p.paidAtoms),'Position的accrued/paid/未领金额不一致。');check(BigInt(p.start)<H_END&&(p.end===null||BigInt(p.end)>=BigInt(p.start))&&BigInt(p.nextUnsettledHour)>=BigInt(p.start)&&BigInt(p.nextUnsettledHour)<=(p.end===null?H_END:BigInt(p.end)<H_END?BigInt(p.end):H_END),'Position区间或覆盖游标不一致。');return p;}

export function checkedMiningRead(result,query){
  readonly(result);check(typeof result.decision==='string'&&!Object.hasOwn(result,'intent'),'读取不能返回交易intent。');if(result.decision!=='MINING_READ')return null;
  const s=result.summary;check(result.readStateVerified===true&&object(s)&&s.actor===query.actor&&s.knownRootsOnly===true&&s.walletDiscoveryComplete===false&&s.futureDailyPayoutGuaranteed===false,'看板未绑定实际读取范围与Actor。');
  uint(s.contextSlot);uint(s.nextNonce);check(String(result.contextSlot)===s.contextSlot,'看板context不一致。');check(object(s.clock)&&object(s.emission)&&object(s.processedWeights)&&object(s.treasury)&&object(s.claimable),'看板字段缺失。');
  const e=s.emission,w=s.processedWeights,t=s.treasury;for(const k of ['slot','unixTimestamp','currentBoundary'])uint(s.clock[k]);
  check(e.totalSupplyLAB==='100000000'&&e.totalSupplyAtoms==='100000000000000'&&e.decimals===6&&e.endHour===String(H_END),'LAB总量或排放范围不一致。');for(const k of ['maturedHours','processedFrontier','backlogHours','scheduledDueAtoms','notYetSynchronizedAtoms'])uint(e[k]);check(BigInt(e.processedFrontier)<=BigInt(e.maturedHours)&&BigInt(e.maturedHours)<=H_END&&BigInt(e.backlogHours)===BigInt(e.maturedHours)-BigInt(e.processedFrontier),'成熟小时和已处理前沿不一致。');check(typeof e.scheduleEnded==='boolean'&&typeof e.emissionClosed==='boolean','缺少排放状态。');
  for(const k of ['normalWeight','kWeight','combinedWeight','denominator','denominatorFloor'])uint(w[k],U128);for(const k of ['asOfHour','rootCount','activeDirectoryCount','eventCount','eventCursor'])uint(w[k]);
  const total=BigInt(w.normalWeight)+BigInt(w.kWeight);check(w.meaning==='PROCESSED_REGISTRY_FRONTIER'&&w.currentWallClockDenominatorGuaranteed===false&&w.asOfHour===e.processedFrontier&&w.denominatorFloor===String(FLOOR)&&w.sharedFloorApplications===1&&BigInt(w.combinedWeight)===total&&BigInt(w.denominator)===(total>FLOOR?total:FLOOR)&&(BigInt(w.kWeight)===0n||BigInt(w.kWeight)===K_WEIGHT)&&BigInt(w.eventCursor)<=BigInt(w.eventCount),'已处理权重或共享分母不一致。');
  for(const k of ['asOfHour','lockedAtoms','pendingAtoms','certifiedAtoms','sealedAtoms','manufactureBurnedAtoms','paidAtoms','bookSumAtoms','mintSupplyAtoms','reserveAtoms','circulatingOutsideReserveAtoms','unsolicitedReserveAtoms','externalBurnedAtoms'])uint(t[k]);
  check(t.donationsCreateRewards===false&&t.externalBurnsCreateRewards===false&&BigInt(t.bookSumAtoms)===['lockedAtoms','pendingAtoms','certifiedAtoms','sealedAtoms'].reduce((n,k)=>n+BigInt(t[k]),0n)&&BigInt(t.reserveAtoms)===BigInt(t.bookSumAtoms)+BigInt(t.unsolicitedReserveAtoms)&&BigInt(t.mintSupplyAtoms)===BigInt(t.reserveAtoms)+BigInt(t.circulatingOutsideReserveAtoms)&&BigInt(t.mintSupplyAtoms)+BigInt(t.manufactureBurnedAtoms)+BigInt(t.externalBurnedAtoms)===100000000000000n,'实际金库、捐入或外部销毁账目不一致。');
  check(Array.isArray(s.roots)&&s.roots.length===query.instancesHex.length,'返回实例范围与查询不一致。');const roots=new Set(),seen=new Set();let claim=0n,all=0n,count=0,known=0n;
  for(const r of s.roots){check(object(r)&&query.instancesHex.includes(id(r.instanceHex))&&!roots.has(r.instanceHex),'返回了重复或未请求的实例。');roots.add(r.instanceHex);actor(r.owner);check(r.lifecycle===0||r.lifecycle===1,'生命周期无效。');uint(r.intrinsicOrdinaryWeight,U128);uint(r.futureOrdinaryWeight,U128);uint(r.actorFutureOrdinaryWeight,U128);check(r.futureWeightIsPotentialOnly===true&&r.historicalDebtMustBeClaimed===false&&(r.lifecycle===0||r.futureOrdinaryWeight==='0'),'成品潜在权重或历史权益声明不一致。');for(const k of ['ordinaryCount','kActivationCount','coverageSequence','nextCoverageHour'])uint(r[k]);nullable(r.ordinaryEnd);nullable(r.kEnd);check(r.ordinaryIntervalOpen===(r.ordinaryEnd===null)&&r.kIntervalOpen===(r.kEnd===null)&&r.kStatusSource==='ROOT_REG_MIRROR','普通/K区间镜像不一致。');
    check(Array.isArray(r.positions)&&r.positions.length<=query.positionPageLimit&&r.positionPageStart===query.positionPageStart,'Position页与查询不一致。');const start=BigInt(query.positionPageStart),end=start+BigInt(query.positionPageLimit);for(const p of r.positions){position(p,start,end,seen);check(BigInt(p.sequence)<BigInt(r.ordinaryCount),'Position超出实际总数。');all+=BigInt(p.claimableAtoms);if(p.beneficiary===query.actor)claim+=BigInt(p.claimableAtoms);count++;}if(r.nextPageStart!==null)uint(r.nextPageStart);
    if(r.activeProcessedDirectory!==null){const d=r.activeProcessedDirectory;uint(d.sequence);uint(d.currentSequence);check(BigInt(d.currentSequence)<BigInt(r.ordinaryCount),'已处理Directory序号超出历史范围。');position(d.position,BigInt(d.currentSequence),BigInt(d.currentSequence)+1n,new Set());known+=BigInt(d.position.weight);}
  }
  uint(s.knownProcessedOrdinaryWeight,U128);check(BigInt(s.knownProcessedOrdinaryWeight)===known&&known<=BigInt(w.normalWeight),'已知Directory权重重复或超出全网。');
  const c=s.claimable;check(c.scope==='LISTED_POSITION_PAGES_ONLY'&&c.walletTotalKnown===false&&c.immutableBeneficiaryRequired===true&&c.listedPositionCount===count&&uint(c.actorAtoms)===String(claim)&&uint(c.allListedBeneficiariesAtoms)===String(all),'未领金额不属于实际页面或固定受益人。');
  if(BigInt(w.kWeight)===0n)check(s.currentK===null,'零K权重不能声明活跃K。');else{const k=s.currentK;check(object(k)&&k.processedActive===true&&k.source==='ACTUAL_PROCESSED_REGISTRY_AND_ACTIVATION'&&k.weight===w.kWeight,'缺少实际已处理K记录。');id(k.activationIdHex);id(k.instanceHex);id(k.ordinaryPositionIdHex);actor(k.beneficiary);uint(k.start);nullable(k.end);uint(k.globalSequence);uint(k.directorySequence);uint(k.ordinarySequence);check(k.physicalIntervalOpen===(k.end===null)&&typeof k.withinWallClockInterval==='boolean','K状态不一致。');}
  return freeze({query:copy(query),summary:copy(s)});
}

function intentAccounts(intent){const roles={SYNC_EMISSION:['LABMint','LABReserve','LABAuth','Treasury','Registry'],OPEN_HOUR:['LABMint','LABReserve','LABAuth','Treasury','Registry','Hour','NextEvent'],APPLY_EVENT:['Registry','Event','Directory','Position'],EMPTY_SKIP:['LABMint','LABReserve','LABAuth','Treasury','Registry','CurrentHour','NextEvent'],ADVANCE_FROZEN_HOUR:['Registry','Hour'],MATERIALIZE_HOUR:['LABMint','LABReserve','LABAuth','Treasury','Registry','Hour'],CLOSE_FINAL_HOUR:['Registry','Hour'],EXIT_ORDINARY:['Registry','Root','RootReg','Position','OrdinaryEndEvent'],TRANSFER_ROOT:['Registry','Root','RootReg']},seen=new Set(),expected=roles[intent.operation];check(expected&&Array.isArray(intent.suffix)&&intent.suffix.length===expected.length,'固定账户数量或操作不正确。');for(const [i,row]of intent.suffix.entries()){check(object(row)&&row.name===expected[i],'固定账户顺序不正确。');const a=actor(row.address);check(!seen.has(a),'固定账户不能重复。');seen.add(a);}for(const row of intent.dynamicAccounts??[]){check(object(row)&&typeof row.writable==='boolean'&&row.signer===false,'动态账户格式不正确。');const a=actor(row.address);check(!seen.has(a),'动态账户不能重复或引用固定账户。');seen.add(a);}}
export function checkedMiningPlan(r,source,q){
  check(['global','hour','lifecycle'].includes(source),'未知规划来源。');readonly(r);check(typeof r.decision==='string','规划缺少明确决策。');if(r.decision!=='ACTION'){check(!Object.hasOwn(r,'intent'),'等待或阻塞结果不能保留intent。');return null;}
  check(r.requiresSimulation===true,'精确规划仍须明确模拟。');uint(String(r.contextSlot));const intent=parseIntent(json(r.intent)),h=intent.payloadHex;intentAccounts(intent);check(Object.keys(RESOURCES).every(k=>intent.resources[k]===RESOURCES[k]),'规划改变了固定资源预算。');check(!intent.feePayer||intent.feePayer===q.actor,'费用支付人不属于本次Actor。');if(r.actor!==undefined)check(r.actor===q.actor,'Actor与当前输入不一致。');
  const lens={SYNC_EMISSION:8,OPEN_HOUR:16,ADVANCE_FROZEN_HOUR:16,APPLY_EVENT:24,EMPTY_SKIP:24,MATERIALIZE_HOUR:32,CLOSE_FINAL_HOUR:16,EXIT_ORDINARY:56,TRANSFER_ROOT:88};check(lens[intent.operation]&&h.length===lens[intent.operation]*2&&le(h,h.length/2-8,8)===BigInt(q.maxRent),'规划载荷长度或租存上限不一致。');
  if(source==='global')check(['SYNC_EMISSION','OPEN_HOUR','ADVANCE_FROZEN_HOUR','APPLY_EVENT','EMPTY_SKIP','MATERIALIZE_HOUR'].includes(intent.operation),'全网推进返回了其他操作。');
  else if(source==='hour'){check(intent.operation==='CLOSE_FINAL_HOUR'&&le(h,0,8)===BigInt(q.hour),'关闭小时与请求不一致。');const p=r.preview;check(object(p)&&p.refundIsObservedBalance===true&&p.rentMinimumQuoted===false&&p.rewardsChanged===false,'缺少实际原始开立者退款信息。');actor(p.refundRecipient);uint(p.observedRefundLamports);const dynamic=intent.dynamicAccounts??[];check(p.refundRecipient===q.actor?dynamic.length===0:dynamic.length===1&&dynamic[0].address===p.refundRecipient&&dynamic[0].writable===true&&dynamic[0].signer===false,'退款账户被改向。');}
  else{
    const p=r.preview;check(object(p)&&(p.instanceHex??p.instance)===q.instanceHex&&p.oldOwner===q.actor&&p.newOwner===(q.kind==='transfer'?q.newOwner:q.actor)&&p.preservesHistoricalBeneficiaries===true&&p.historicalDebtMustBeClaimed===false,'生命周期规划改变了实例、所有人或历史权益。');uint(p.rootRevision);uint(p.registrationRevision);uint(p.ordinaryEnd);uint(p.kEnd);check(h.slice(0,64)===q.instanceHex,'生命周期载荷引用了其他实例。');
    if(q.kind==='transfer')check(intent.operation==='TRANSFER_ROOT'&&le(h,32,8)===BigInt(p.rootRevision)&&le(h,40,8)===BigInt(p.registrationRevision)&&h.slice(96,160)===addressBytes(q.newOwner)&&(intent.dynamicAccounts??[]).length===0,'转让载荷或接收人不一致。');
    else{check(intent.operation==='EXIT_ORDINARY'&&le(h,40,8)===BigInt(p.rootRevision)&&le(h,32,8)===BigInt(uint(p.positionSequence)),'退出序号或revision不一致。');const d=intent.dynamicAccounts??[],ev=p.events;check(Array.isArray(ev)&&(d.length===0&&ev.length===1||d.length===4&&ev.length===2),'退出K分支或事件数量不正确。');check(ev.at(-1).kind==='ORDINARY_END'&&BigInt(uint(ev.at(-1).due))===(BigInt(p.ordinaryEnd)<H_END?BigInt(p.ordinaryEnd):H_END),'普通结束事件未绑定实际结束边界。');if(d.length===4)check(d.every(v=>v.writable&&!v.signer)&&ev[0].kind==='K_END'&&BigInt(uint(ev[0].sequence))+1n===BigInt(uint(ev[1].sequence))&&BigInt(uint(ev[0].due))===BigInt(p.kEnd)&&BigInt(p.kEnd)<=H_END,'K结束事件顺序不正确。');}
  }
  return freeze({actor:q.actor,source,request:copy(q),intent:copy(intent),result:copy(r)});
}

export function handoffMiningPosition(document,dashboard,selection){const [instanceHex,sequence]=selection.split(':');const r=dashboard?.summary.roots.find(v=>v.instanceHex===instanceHex),p=r?.positions.find(v=>v.sequence===sequence);check(p,'请明确选择本次实际读到的历史Position。');handoffKnownAsset(document,{actor:dashboard.query.actor,instanceHex,positionPageStart:sequence,positionPageLimit:'1'});}
export function handoffMiningAsset(document,dashboard,instanceHex){check(dashboard?.summary.roots.some(r=>r.instanceHex===instanceHex),'请明确选择本次实际读到的作品。');handoffKnownAsset(document,{actor:dashboard.query.actor,instanceHex});}

export async function mountMiningOperations(document,{fetchImpl=globalThis.fetch}={}){
  const $=id=>document.getElementById(id);if(!$('mining-view'))return;const state={config:null,generation:0,mode:'dashboard',dashboard:null,plan:null,result:null};let active=null,busy=false,configController=null,configBusy=false,lastDashboard=null;
  const values=()=>({actor:$('mining-actor').value,instancesHex:$('mining-instances').value,positionPageStart:$('mining-page-start').value,positionPageLimit:$('mining-page-limit').value,maxRent:$('mining-max-rent').value,hour:$('mining-hour').value,instanceHex:$('mining-instance').value,newOwner:$('mining-new-owner').value});
  const message=(t,error=false)=>{$('mining-message').textContent=t;$('mining-message').className=`native-message${error?' error':''}`;};
  const summary=(target,rows)=>{target.replaceChildren();for(const [label,v]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=typeof v==='object'?json(v):String(v);target.append(dt,dd);}};
  const valid=fn=>{try{fn();return true;}catch{return false;}};
  function render(){
    const enabled=trustedConsoleConfig(state.config),ready=enabled&&!busy&&!configBusy;
    for(const name of ['actor','instances','page-start','page-limit','max-rent','hour','instance','new-owner'])$('mining-'+name).disabled=!enabled;
    for(const [button,builder]of [['read',()=>miningReadRequest(values())],['global-plan',()=>miningGlobalRequest(values())],['hour-plan',()=>miningHourCloseRequest(values())],['exit-plan',()=>miningLifecycleRequest(values(),'exit')],['transfer-plan',()=>miningLifecycleRequest(values(),'transfer')]])$('mining-'+button).disabled=!ready||!valid(builder);
    $('mining-use-intent').disabled=!ready||!state.plan||state.plan.generation!==state.generation;$('mining-open-position').disabled=!ready||!state.dashboard||!$('mining-position').value;$('mining-position').disabled=!ready||!state.dashboard;$('mining-root').disabled=!ready||!state.dashboard;$('mining-open-asset').disabled=!ready||!state.dashboard||!$('mining-root').value;$('mining-reload').disabled=busy||configBusy;
    for(const mode of ['dashboard','lifecycle']){$('mining-tab-'+mode).classList.toggle('active',state.mode===mode);$('mining-tab-'+mode).setAttribute('aria-pressed',String(state.mode===mode));$('mining-'+mode+'-panel').hidden=state.mode!==mode;}
    if(lastDashboard!==state.dashboard){lastDashboard=state.dashboard;$('mining-position').replaceChildren();$('mining-root').replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='选择本次读取的实际历史Position';$('mining-position').append(placeholder);const rootPlaceholder=document.createElement('option');rootPlaceholder.value='';rootPlaceholder.textContent='选择本次读取的作品';$('mining-root').append(rootPlaceholder);const s=state.dashboard?.summary;
      summary($('mining-overview'),s?[['已处理全网前沿 / 成熟小时',`${s.emission.processedFrontier} / ${s.emission.maturedHours}`],['待处理小时',s.emission.backlogHours],['已处理普通权重',s.processedWeights.normalWeight],['已处理首创K权重',s.processedWeights.kWeight],['共享分母（应用一次下限）',s.processedWeights.denominator],['本页Actor已计债未领 LAB 原子',s.claimable.actorAtoms],['排放日程已结束 / 前沿已完成',`${s.emission.scheduleEnded} / ${s.emission.emissionClosed}`],['实际金库',s.treasury],['实际已处理K',s.currentK??'无']]:[]);
      $('mining-dashboard-json').textContent=s?json(s):'尚未读取实际记录。';for(const r of s?.roots??[]){const rootOption=document.createElement('option');rootOption.value=r.instanceHex;rootOption.textContent=`${r.instanceHex.slice(0,12)}… · ${r.lifecycle===0?'未消耗':'已用于合成'} · 普通历史 ${r.ordinaryCount} 段`;$('mining-root').append(rootOption);for(const p of r.positions){const option=document.createElement('option');option.value=`${r.instanceHex}:${p.sequence}`;option.textContent=`${r.instanceHex.slice(0,10)}… #${p.sequence} · 固定受益人 ${p.beneficiary} · 未领 ${p.claimableAtoms} 原子`;$('mining-position').append(option);}}$('mining-position').value='';$('mining-root').value='';
    }
    $('mining-result-badge').textContent=busy?'正在只读核对':state.result?.decision??'等待明确操作';$('mining-result-badge').className=`result-status${state.plan?' pass':''}`;$('mining-result-json').textContent=state.result?json(state.result):'尚无当前输入的操作草案。';
    summary($('mining-plan-summary'),state.plan?[['操作',state.plan.intent.operation],['nonce（未预留）',state.plan.intent.nonce],['精确请求',state.plan.request],['预览',state.plan.result.preview??'单步全网推进；不等于个人计债或领取'],['固定资源预算',state.plan.intent.resources]]:[]);
  }
  function invalidate({clearDashboard=false,text='输入已改变；旧操作草案已清除。'}={}){active?.abort();active=null;busy=false;state.generation++;state.plan=null;state.result=null;if(clearDashboard)state.dashboard=null;message(text);render();}
  async function run(action,body,apply){if(busy||configBusy||!trustedConsoleConfig(state.config))return;state.generation++;state.plan=null;state.result=null;if(action==='mining-read')state.dashboard=null;const generation=state.generation,controller=new AbortController();active=controller;busy=true;message('正在执行本次明确的只读核对…');render();try{const result=await nativeRequest(action,body,{fetchImpl,signal:controller.signal});if(generation!==state.generation||active!==controller)return;apply(result);render();}catch(e){if(generation===state.generation&&active===controller){state.plan=null;state.result=null;message(e.message,true);}}finally{if(active===controller){active=null;busy=false;render();}}}
  async function loadConfig(){configController?.abort();const controller=new AbortController();configController=controller;configBusy=true;state.config=null;invalidate({clearDashboard:true,text:'正在读取服务端配置；不会连接钱包。'});$('mining-config-badge').textContent='读取配置中';try{const r=await nativeRequest('config',undefined,{fetchImpl,signal:controller.signal});if(configController!==controller)return;state.config=freeze(copy(r));const enabled=trustedConsoleConfig(r);$('mining-config-badge').textContent=enabled?'已启用 · 只读规划':'未启用 · 本地模式';$('mining-config-note').textContent=enabled?'只读取服务端固定网络的实际记录。请求得到精确草案后，仍需进入链上操作逐项执行。':'链上读取与规划默认关闭。此页展示操作入口与口径说明，不展示假余额或预估日产量；本地构造仍可使用。';message(enabled?'请输入Actor与已知实例ID；留空实例列表可只看全网进度。':'链上规划未启用，未连接钱包或发送请求。');}catch(e){if(configController===controller){$('mining-config-badge').textContent='配置不可用 · 保持关闭';message(e.message,true);}}finally{if(configController===controller){configController=null;configBusy=false;render();}}}
  const identity=new Set(['actor','instances','page-start','page-limit']);for(const name of ['actor','instances','page-start','page-limit','max-rent','hour','instance','new-owner'])for(const event of ['input','change'])$('mining-'+name).addEventListener(event,()=>invalidate({clearDashboard:identity.has(name)}));
  $('mining-position').addEventListener('change',()=>invalidate());
  $('mining-root').addEventListener('change',()=>{const selected=state.dashboard?.summary.roots.find(r=>r.instanceHex===$('mining-root').value),field=$('mining-instance');field.value=selected?.instanceHex??'';const EventClass=document.defaultView?.Event??globalThis.Event;field.dispatchEvent(new EventClass('input',{bubbles:true}));message(selected?'已带入所选作品；退出或转让仍须重新核对实际状态。':'已清除作品选择；没有规划或执行操作。');});
  for(const mode of ['dashboard','lifecycle'])$('mining-tab-'+mode).addEventListener('click',()=>{state.mode=mode;invalidate({clearDashboard:true,text:'面板已切换；旧规划不再可用。'});});
  document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{invalidate({clearDashboard:true,text:'视图已切换；旧规划已清除。'});document.querySelectorAll('.view').forEach(view=>{view.hidden=view.id!==`${button.dataset.view}-view`;});if(button.dataset.view==='mining')$('page-title').textContent='持续挖矿与权益';}));
  const request=builder=>{try{return builder();}catch(e){message(e.message,true);return null;}};
  $('mining-read').addEventListener('click',()=>{const q=request(()=>miningReadRequest(values()));if(q)void run('mining-read',q,r=>{state.dashboard=checkedMiningRead(r,q);state.result=copy(r);message(state.dashboard?'已读取实际记录。全网推进、个人补记和领取分别执行；本页金额只覆盖实际列出的Position。':`当前决策：${r.decision}；未生成可用交易。`);});});
  const plan=(action,source,q)=>run(action,q,r=>{const p=checkedMiningPlan(r,source,q);state.result=copy(r);if(p)state.plan={...p,generation:state.generation};message(p?'得到一个未执行草案；nonce未预留。送入链上操作后，明确准备、检查、模拟、签名和发送。':`当前决策：${r.decision}；没有可用intent。`);});
  $('mining-global-plan').addEventListener('click',()=>{const q=request(()=>miningGlobalRequest(values()));if(q)void plan('global-plan','global',q);});$('mining-hour-plan').addEventListener('click',()=>{const q=request(()=>miningHourCloseRequest(values()));if(q)void plan('hour-close-plan','hour',q);});for(const kind of ['exit','transfer'])$('mining-'+kind+'-plan').addEventListener('click',()=>{const q=request(()=>miningLifecycleRequest(values(),kind));if(q)void plan('lifecycle-plan','lifecycle',q);});
  $('mining-use-intent').addEventListener('click',()=>{if(!busy&&trustedConsoleConfig(state.config)&&state.plan?.generation===state.generation)try{handoffGuidedIntent(document,state.plan);}catch(e){message(e.message,true);}});
  $('mining-open-position').addEventListener('click',()=>{if(!busy&&trustedConsoleConfig(state.config)&&state.dashboard)try{handoffMiningPosition(document,state.dashboard,$('mining-position').value);}catch(e){message(e.message,true);}});
  $('mining-open-asset').addEventListener('click',()=>{if(!busy&&trustedConsoleConfig(state.config)&&state.dashboard)try{handoffMiningAsset(document,state.dashboard,$('mining-root').value);}catch(e){message(e.message,true);}});
  $('mining-recovery').addEventListener('click',()=>{const nav=[...document.querySelectorAll('.nav-item')].find(v=>v.dataset.view==='native');nav?.click();});$('mining-reload').addEventListener('click',loadConfig);document.addEventListener?.('biolab-auth-change',()=>{state.config=null;invalidate({clearDashboard:true});void loadConfig();}); await loadConfig();return {state,render};
}
if(typeof document!=='undefined')void mountMiningOperations(document).catch(e=>{const el=document.getElementById('mining-message');if(el){el.textContent=`挖矿规划保持关闭：${e.message}`;el.className='native-message error';}});
